// stlport
// Size-optimised (/O1) emission of vector<bool> members that retail keeps
// out of line in a size-optimised unit: push_back and the const subscript.
// The default-flag explicit instantiation in stlport_vector_bool_assignment.cpp
// emits both at /O2 shape which does not match retail.
#define BFME_STLP_NODE_ALLOC
#include "PreRTS.h"

#include <vector>

typedef _STL::vector<bool> BoolVector;

extern void (BoolVector::*const g_boolVectorPushBack)(bool);
void (BoolVector::*const g_boolVectorPushBack)(bool) = &BoolVector::push_back;

extern bool (BoolVector::*const g_boolVectorConstSubscript)(unsigned int) const;
bool (BoolVector::*const g_boolVectorConstSubscript)(unsigned int) const = &BoolVector::operator[];